rss.channel:
    {{ site.title | default: site.name | xml_escape }}
    {{ "/" | absolute_url }}
    {{ site.description | xml_escape }}
    {%- if site.lang %}
    {{ site.lang }}
    {%- endif %}
    {{ site.time | date_to_rfc822 }}

{%- for post in posts %}
  {%- assign post_url = post.url | absolute_url %}


      {{ post.title | strip_html | strip | xml_escape }}
      {{ post_url }}
      {{ post_url }}
      {{ post.date | date_to_rfc822 }}
    {%- comment -%} devto_tags first, so new imports already carry the tags chosen for dev.to. {%- endcomment -%}
    {%- assign tags = post.devto_tags | default: post.tags | default: post.categories %}
    {%- for tag in tags %}
      {{ tag | xml_escape }}
    {%- endfor %}
      {{ post.description | default: post.excerpt | strip_html | strip_newlines | truncatewords: 60 | xml_escape }}
    {%- comment -%} The dev.to cover: devto_cover, else the post image (jekyll-og-image sets it). {%- endcomment -%}
    {%- comment -%} Unlike content links, image paths leave baseurl out (Chirpy and jekyll-og-image add it when rendering). {%- endcomment -%}
    {%- assign cover = post.devto_cover | default: post.image | devto_url: site_root %}
    {%- if cover != "" %}
      {{ cover | xml_escape }}
    {%- endif %}
    {%- if post.devto_tags %}
      {{ post.devto_tags | join: "," | xml_escape }}
    {%- endif %}
    {%- if post.devto_series %}
      {{ post.devto_series | xml_escape }}
    {%- endif %}
      {{ post.content | devto_html: site_url | xml_escape }}

{%- endfor %}
